{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "The primary outcome was pain during endometrial biopsy or endometrial sampling, measured on a 0-10 compatible visual analogue, numerical rating, or equivalent pain scale, with higher scores indicating worse pain. The primary effect direction was active intervention minus comparator; negative mean differences therefore favored the intervention. Secondary and supplementary outcomes included binary high-pain outcomes, pain at other procedure-related timepoints, need for additional analgesia, participant satisfaction or willingness to undergo repeat biopsy, procedure failure, and adverse events or complications.",
      "reason": "The manuscript explicitly lists and defines the primary outcome (pain during biopsy/sampling on a 0-10 scale) and lists secondary/supplementary outcomes."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "When several pain timepoints were available, the closest clearly intra-procedural biopsy or sampling pain timepoint was selected.",
      "reason": "The manuscript specifies the time frame for the primary outcome (intra-procedural pain) and how it was selected when multiple timepoints were available."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "For the primary continuous meta-analysis, comparisons had to meet all of the following additional criteria: ... the outcome had to be pain during biopsy or sampling, or the closest clearly intra-procedural biopsy pain timepoint; and the outcome had to be extractable as sample size, mean, and standard deviation on a 0-10 compatible pain scale... Studies reporting medians and ranges only, interquartile ranges only, ordinal verbal rating scale distributions, binary high-pain thresholds, unresolved variance units... were not included in the primary estimate.",
      "reason": "The manuscript clarifies that not all compatible results were sought for the primary meta-analysis; it explicitly states that only studies with extractable means and standard deviations were included, while others were excluded or summarized narratively."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Studies reporting medians and ranges only, interquartile ranges only, ordinal verbal rating scale distributions, binary high-pain thresholds, unresolved variance units, nonpharmacologic device adjuncts, or co-intervention designs not matching the primary estimand were not included in the primary estimate. When clinically relevant, such records were summarized narratively, tabulated as non-pooled evidence, or assigned to prespecified sensitivity analyses.",
      "reason": "The manuscript describes the process for handling results that did not meet the criteria for the primary meta-analysis (e.g., narrative summary, sensitivity analysis)."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence of changes to outcome-domain inclusion, definitions, or importance during the review process."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence of changes to the processes for selecting results within eligible outcome domains."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "Risk of bias for randomized trials was assessed using the Cochrane RoB 2 framework at the outcome level, with primary emphasis on pain during biopsy or sampling [9]. ... Certainty of evidence was assessed using the GRADE approach for outcomes prioritized for the Summary of Findings [10].",
      "reason": "The manuscript identifies pain during biopsy or sampling as the primary outcome and notes it was prioritized for the Summary of Findings and GRADE assessment."
    }
  ],
  "confidence": 100
}

